public class ResilientNioHandler {
    private final Selector selector;

    public ResilientNioHandler(Selector selector) {
        this.selector = selector;
    }

    public void processKeys() {
        Set<SelectionKey> selectedKeys = selector.selectedKeys();
        Iterator<SelectionKey> iterator = selectedKeys.iterator();

        while (iterator.hasNext()) {
            SelectionKey key = iterator.next();
            iterator.remove();

            if (!key.isValid()) {
                continue;
            }

            try {
                if (key.isReadable()) {
                    readData(key);
                }
            } catch (IOException e) {
                // Production fix: Handle connection drop gracefully without crashing the selector
                handleIoException(key, e);
            }
        }
    }

    private void readData(SelectionKey key) throws IOException {
        SocketChannel channel = (SocketChannel) key.channel();
        ByteBuffer buffer = ByteBuffer.allocateDirect(1024);
        int bytesRead = channel.read(buffer);
        if (bytesRead == -1) {
            channel.close();
            key.cancel();
        } else if (bytesRead > 0) {
            buffer.flip();
            // Process buffer data safely
            buffer.clear();
        }
    }

    private void handleIoException(SelectionKey key, IOException e) {
        try {
            key.channel().close();
        } catch (IOException ignored) {
            // Suppress close exception during teardown
        }
        key.cancel();
    }
}
